                /** @description Any of `low`, `normal` and `high`, comma-separated. */
                importance?: string;
                /** @description Additional fields to include, as a comma-separated list. `raw` is the provider's original payload. `extendedProperties` is the provider's extended properties. `conferencingSettings` is available only when you retrieve one event. */
                include?: string;
                isAllDay?: boolean;
                /** @description The maximum number of results in one page. Defaults to 100. */
                limit?: number;
                /** @description Returns events whose location contains this text. */
                location?: string;
                /** @description Returns events organized by any of these email addresses, comma-separated. */
                organizer?: string;
                /** @description Limits `accountIds` or `subjectId` to accounts on this provider. */
                provider?: "google" | "microsoft" | "pyas";
                /** @description Returns events whose title, description or location contains this text. */
                q?: string;
                /** @description `true` returns only events in a recurring series. `false` returns only single events. */
                recurring?: boolean;
                /** @description Any of `busy`, `free`, `tentative`, `outOfOffice` and `workingElsewhere`, comma-separated. */
                showAs?: string;
                /** @description The sort order: `start` (requires `expand=true`) or `updated`. */
                sort?: string;
                /** @description Any of `confirmed`, `tentative` and `cancelled`, comma-separated. Defaults to `confirmed,tentative`. */
                status?: string;
                /** @description Selects every connected account labeled with this `subjectId`. */
                subjectId?: string;
                /** @description Starts a sync of the time window. Returns every event in the window, with a `syncToken` on the last page. */
                sync?: boolean;
                /** @description The `syncToken` from the last page of a sync. Returns only the changes since that sync. */
